@startuml

class Customer {
  +vatNumber : string
  +name : string
  +phoneNumber : string
  +address : string
}

class Package {
  +identifierCode : string
  +weight : float
  +isUrgent : boolean
}

class DeliveryCenter {
  +name : string
  +address : string
}

class Courier {
  +vatNumber : string
  +name : string
  +phoneNumber : string
}

Customer "1" -- "0..*" Package : sends
Customer "1" -- "0..*" Package : receives
Customer "1" -- "1" DeliveryCenter : is associated with
Package "0..*" -- "1" DeliveryCenter : is delivered to
Package "0..*" -- "1" Courier : is assigned to
Courier "1" -- "1" DeliveryCenter : works in

@enduml

